            "assert tcp('127.0.0.1',5301,'a23.test','AXFR')['rcode']==5\n"
            "soa=udp('127.0.0.1',5301,'a23.test','SOA')\n"
            "assert soa['aa'] and soa['answers'][0][3][:3]==('ns1.a23.test.','hostmaster.a23.test.',2026110301),soa"
