            "assert a('app1.a23.test')==['192.0.2.11'] and a('app2.a23.test')==['192.0.2.12'] and a('ns1.a23.test')==['192.0.2.10']\n"
            "assert a('blocked.a23.test')==['192.0.2.66']\n"
